import {Breadcrumbs, Heading, LinkButton, Stack, ActionMenu, ActionList} from '@primer/react'
import {DownloadIcon} from '@primer/octicons-react'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {useState} from 'react'
import {Banner} from '@primer/react/experimental'
import {useCreateCSV} from '@github-ui/licensing-common/hooks/useCreateCSV'

export function CopilotLicensingHeader() {
  const {basePath, slug} = useNavigation()
  const licensingLink = `${basePath}/enterprise_licensing`
  const csvUsageDownloadUrl = `${basePath}/settings/download_seat_management_usage`
  const csvActivityDownloadUrl = `${basePath}/settings/download_seat_management_activity`
  const policiesLink = `${basePath}/settings/copilot?tab=policies`
  const [showBanner, setShowBanner] = useState(false)
  const [bannerMessage, setBannerMessage] = useState('')
  const [bannerTitle, setBannerTitle] = useState<'CSV Export in Progress' | 'CSV Export Error'>(
    'CSV Export in Progress',
  )
  const [bannerVariant, setBannerVariant] = useState<'critical' | 'success'>('critical')

  const handleResult = (result: string) => {
    if (result === 'success') {
      setBannerMessage(
        'Your activity report is being generated. You will receive an email when it is ready to download.',
      )
      setBannerTitle('CSV Export in Progress')
      setBannerVariant('success')
    } else {
      setBannerMessage('An error occurred while exporting the CSV report.')
      setBannerTitle('CSV Export Error')
      setBannerVariant('critical')
    }
    setShowBanner(true)
  }

  const {loading: csvLoading, makeCSVRequest: csvDownload} = useCreateCSV({
    slug,
    method: 'GET',
    endpoint: csvUsageDownloadUrl,
    onError: () => handleResult('error'),
  })

  const {loading: activityLoading, makeCSVRequest: activityDownload} = useCreateCSV({
    slug,
    endpoint: csvActivityDownloadUrl,
    async: true,
    method: 'GET',
    onSuccess: () => handleResult('success'),
  })

  return (
    <>
      {showBanner && (
        <Banner
          title={bannerTitle}
          hideTitle
          variant={bannerVariant}
          onDismiss={() => setShowBanner(false)}
          className="mb-3"
          data-testid="csv-download-banner"
        >
          {bannerMessage}
        </Banner>
      )}
      <Breadcrumbs>
        <Breadcrumbs.Item href={licensingLink}>Licensing</Breadcrumbs.Item>
        <Breadcrumbs.Item selected>Copilot</Breadcrumbs.Item>
      </Breadcrumbs>
      <Stack justify="space-between" direction="horizontal" className="mt-2" data-testid="licensing-copilot-header">
        <Heading as="h1">Copilot</Heading>
        <Stack direction="horizontal">
          <LinkButton className="fgColor-accent" variant="invisible" href={policiesLink}>
            View policies
          </LinkButton>
          <ActionMenu>
            <ActionMenu.Button
              disabled={csvLoading || activityLoading}
              leadingVisual={DownloadIcon}
              data-testid="download-csv-button"
            >
              CSV Report
            </ActionMenu.Button>
            <ActionMenu.Overlay>
              <ActionList>
                <ActionList.Item onSelect={activityDownload} loading={activityLoading}>
                  Activity report (new)
                  <ActionList.Description variant="block">
                    Includes more Copilot Activity details
                  </ActionList.Description>
                </ActionList.Item>
                <ActionList.Divider />
                <ActionList.Item onSelect={csvDownload} loading={csvLoading}>
                  Usage report (legacy)
                  <ActionList.Description variant="block">Sunsetting Oct 23, 2025</ActionList.Description>
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </Stack>
      </Stack>
    </>
  )
}

try{ CopilotLicensingHeader.displayName ||= 'CopilotLicensingHeader' } catch {}