import {ActionList, ActionMenu, Button, Dialog} from '@primer/react'
import type {Organization} from '../../types'
import {ListItem} from '@github-ui/list-view/ListItem'
import {GitHubAvatar} from '@github-ui/github-avatar'
import styles from './CopilotOrganizationGrantAccessDialog.module.css'
import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import pluralize from 'pluralize'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {clsx} from 'clsx'
import {useState} from 'react'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useNavigate} from '@github-ui/use-navigate'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {CopilotAccessListPlanOptions} from '../../utils/copilot-plan-options'
import {capitalizePlan} from '../../utils/string-utils'
import {Banner} from '@primer/react/experimental'
import {SearchBar} from '@github-ui/licensing-common/components/SearchBar'
import {useEnterpriseCopilotAccessFetch} from '../../hooks/use-enterprise-copilot-access-fetch'
import {XIcon} from '@primer/octicons-react'

export interface CopilotOrganizationGrantAccessDialogProps {
  onDialogClose: () => void
}

export function CopilotOrganizationGrantAccessDialog(props: CopilotOrganizationGrantAccessDialogProps) {
  const {basePath} = useNavigation()
  const navigate = useNavigate()
  const [searchQuery, setSearchQuery] = useState('')

  // Use the organization search hook
  const {
    results: searchResults,
    loading: isLoading,
    isEmpty,
  } = useEnterpriseCopilotAccessFetch({
    basePath,
    searchQuery,
    searchType: 'organizations',
    withAccess: false,
  })

  const [selectedOrganizations, setSelectedOrganizations] = useState<Organization[]>([])
  const [showErrorBanner, setShowErrorBanner] = useState(false)

  const organizationsWithPlans = searchResults.map(org => {
    const selectedOrg = selectedOrganizations.find(selected => selected.id === org.id)
    return selectedOrg || org
  })

  const handlePlanSelection = (organization: Organization, option: {text: string; value: string}) => {
    if (option.value === 'disabled') {
      handleOrganizationRemove(organization.id)
      return
    }

    const updatedOrganizations = [...selectedOrganizations]
    const existingIndex = updatedOrganizations.findIndex(org => org.id === organization.id)

    const updatedOrg = {...organization, newPlan: option.value}

    if (existingIndex >= 0) {
      updatedOrganizations[existingIndex] = updatedOrg
    } else {
      updatedOrganizations.push(updatedOrg)
    }

    setSelectedOrganizations(updatedOrganizations)
  }

  const handleOrganizationRemove = (organizationId: number) => {
    setSelectedOrganizations(selectedOrganizations.filter(org => org.id !== organizationId))
  }

  const handleBulkEnablement = async () => {
    const planEnablementMap: Record<string, number[]> = {
      business: [],
      enterprise: [],
    }

    for (const org of selectedOrganizations) {
      if (org.newPlan && org.newPlan !== org.copilotPlan) {
        planEnablementMap[org.newPlan]?.push(org.id)
      }
    }

    let anyErrors = false
    for (const [plan, orgs] of Object.entries(planEnablementMap)) {
      if (orgs.length > 0) {
        const formData = new FormData()
        formData.append('enablement', plan)
        for (const org of orgs) {
          formData.append('organizations[]', org.toString())
        }

        try {
          const response = await verifiedFetch(`${basePath}/settings/update_copilot_bulk_org_enablement`, {
            method: 'PUT',
            body: formData,
          })
          if (!response.ok) {
            anyErrors = true
          }
        } catch {
          anyErrors = true
        }
      }
    }
    if (anyErrors) {
      setShowErrorBanner(true)
    } else {
      navigate(`${basePath}/enterprise_licensing/copilot?tab=organizations`)
    }
  }

  return (
    <>
      <Dialog
        title="Grant access to organizations"
        subtitle="Allow organizations to assign either Copilot Business or Copilot Enterprise licenses to their users"
        onClose={props.onDialogClose}
        footerButtons={[
          {buttonType: 'default', content: 'Cancel', onClick: props.onDialogClose},
          {
            buttonType: 'primary',
            content: 'Grant access',
            onClick: handleBulkEnablement,
            disabled: selectedOrganizations.length === 0,
          },
        ]}
      >
        {showErrorBanner && (
          <Banner
            title="Copilot Access Grant Error"
            hideTitle
            variant="critical"
            onDismiss={() => setShowErrorBanner(false)}
            className="mb-3"
            data-testid="copilot-grant-access-error-banner"
          >
            {'An error occurred while granting Copilot access to some organizations. Please refresh and try again.'}
          </Banner>
        )}

        <div className="flex-1 mb-3" data-testid="licensing-copilot-organization-grant-search">
          <SearchBar
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            placeholder={'Search for organizations'}
            ariaLabel={'Search for organizations'}
          />
        </div>

        {searchQuery && (
          <ListView
            title={'Organizations'}
            metadata={
              <ListViewMetadata
                title={<span className="text-bold">{pluralize('organization', searchResults.length, true)}</span>}
              />
            }
            className="border border-muted rounded-2 mb-3"
            data-testid="licensing-copilot-organization-grant-access-list"
          >
            {isLoading ? (
              <ListItem title={<span />}>
                <div className={`text-center p-3 ${styles.stretchedText}`}>Loading organizations...</div>
              </ListItem>
            ) : isEmpty || organizationsWithPlans.length === 0 ? (
              <ListItem title={<span />}>
                <div className={`text-center p-3 ${styles.stretchedText}`}>
                  No organizations found matching your search.
                </div>
              </ListItem>
            ) : (
              (organizationsWithPlans as Organization[]).map(organization => (
                <ListItem
                  key={organization.id}
                  data-testid={`org-li-${organization.login}`}
                  title={
                    <div className={`${styles.orgDetails}`}>
                      <div className="d-flex align-items-center">
                        <GitHubAvatar src={organization.avatarUrl} size={16} square className={styles.githubAvatar} />
                        <div className="ml-2">
                          <a href={organization.orgUrl} className="text-bold pb-2">
                            {organization.login}
                          </a>
                        </div>
                      </div>
                    </div>
                  }
                >
                  <div className="mb-0">
                    <ListItemMainContent>
                      <div className={styles.topRightButton}>
                        <ActionMenu>
                          <ActionMenu.Button data-testid={`org-copilot-plan-dropdown-${organization.login}`}>
                            {organization.previousPlan ? (
                              <span className="color-fg-muted">Re-enable Copilot</span>
                            ) : (
                              <>
                                <span className="color-fg-muted">Copilot: </span>
                                {capitalizePlan(organization.newPlan || organization.copilotPlan || 'business')}
                              </>
                            )}
                          </ActionMenu.Button>
                          <ActionMenu.Overlay style={{minWidth: '225px'}}>
                            <ActionList selectionVariant="single">
                              {(organization.previousPlan
                                ? CopilotAccessListPlanOptions.filter(option =>
                                    [organization.previousPlan, organization.copilotPlan].includes(option.value),
                                  )
                                : CopilotAccessListPlanOptions
                              ).map(option => (
                                <ActionList.Item
                                  key={option.value}
                                  selected={
                                    (organization.newPlan || organization.copilotPlan || 'business') === option.value
                                  }
                                  onSelect={() => handlePlanSelection(organization, option)}
                                  data-testid={`org-copilot-plan-${organization.id}-${option.value
                                    .replace('_', '-')
                                    .toLowerCase()}`}
                                >
                                  <span
                                    className={clsx(
                                      option.value === 'disabled' ? 'color-fg-danger' : 'font-weight-normal',
                                    )}
                                  >
                                    {option.text}
                                  </span>
                                  <p className={'color-fg-muted mt-1'}>{option.subtext}</p>
                                </ActionList.Item>
                              ))}
                            </ActionList>
                          </ActionMenu.Overlay>
                        </ActionMenu>
                      </div>
                    </ListItemMainContent>
                  </div>
                </ListItem>
              ))
            )}
          </ListView>
        )}

        {selectedOrganizations.length > 0 && (
          <div className="mb-1">
            <h3 className="mb-2 text-small text-bold">Selected organizations ({selectedOrganizations.length})</h3>
            <div className={styles.selectedOrganizationsContainer}>
              {selectedOrganizations.map(org => (
                <div
                  key={`selected-${org.id}`}
                  data-testid={`selected-org-item-${org.login}`}
                  className={styles.selectedOrgItem}
                >
                  <div className="d-flex align-items-center">
                    <GitHubAvatar src={org.avatarUrl} size={16} square className="mr-2" />
                    <span className="text-small text-bold mr-2">{org.login}</span>
                    <span className="text-small color-fg-muted">
                      (Copilot {capitalizePlan(org.newPlan || org.copilotPlan || 'business')})
                    </span>
                  </div>
                  <Button
                    variant="invisible"
                    size="small"
                    data-testid={`remove-org-${org.id}`}
                    className={styles.removeButton}
                    aria-label={`Remove ${org.login}`}
                    onClick={() => handleOrganizationRemove(org.id)}
                  >
                    <XIcon size={12} />
                  </Button>
                </div>
              ))}
            </div>
          </div>
        )}
      </Dialog>
    </>
  )
}

try{ CopilotOrganizationGrantAccessDialog.displayName ||= 'CopilotOrganizationGrantAccessDialog' } catch {}