import {Button, Dialog} from '@primer/react'
import {ListItem} from '@github-ui/list-view/ListItem'
import styles from './CopilotBusinessTeamGrantAccessDialog.module.css'
import {ListView} from '@github-ui/list-view'
import {useState} from 'react'
import {SearchBar} from '@github-ui/licensing-common/components/SearchBar'
import {CopilotBusinessTeamChangeAccessDialog} from './CopilotBusinessTeamChangeAccessDialog'
import {useEnterpriseCopilotAccessFetch} from '../../hooks/use-enterprise-copilot-access-fetch'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import type {BusinessTeam} from '../../types'

import {XIcon} from '@primer/octicons-react'

export interface CopilotBusinessTeamGrantAccessDialogProps {
  onDialogClose: () => void
}

export function CopilotBusinessTeamGrantAccessDialog(props: CopilotBusinessTeamGrantAccessDialogProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedTeams, setSelectedTeams] = useState<BusinessTeam[]>([])
  const [showConfirmationDialog, setShowConfirmationDialog] = useState(false)
  const {basePath} = useNavigation()

  const {
    results: businessTeams,
    loading,
    isEmpty,
  } = useEnterpriseCopilotAccessFetch({
    basePath,
    searchQuery,
    searchType: 'enterprise_teams',
    withAccess: false,
  })

  const handleTeamSelect = (team: BusinessTeam) => {
    // Check if team is already selected
    if (!selectedTeams.some(selectedTeam => selectedTeam.id === team.id)) {
      setSelectedTeams([...selectedTeams, team])
    }
  }

  const handleTeamRemove = (teamId: number) => {
    setSelectedTeams(selectedTeams.filter(team => team.id !== teamId))
  }

  const handleAddLicenses = () => {
    if (selectedTeams.length > 0) {
      setShowConfirmationDialog(true)
    }
  }

  const handleCloseConfirmationDialog = () => {
    setShowConfirmationDialog(false)
  }

  return (
    <>
      <Dialog
        title="Assign licenses"
        subtitle="Select enterprise teams to give Copilot access to. Users that already have access from an organization or team will only be charged for one license."
        onClose={props.onDialogClose}
        footerButtons={[
          {
            content: 'Cancel',
            buttonType: 'default',
            onClick: props.onDialogClose,
          },
          {
            content: 'Review licenses',
            buttonType: 'primary',
            onClick: handleAddLicenses,
            disabled: selectedTeams.length === 0,
          },
        ]}
      >
        <div className="flex-1" data-testid="licensing-copilot-enterprise-team-grant-search">
          <SearchBar
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            placeholder={'Search teams'}
            ariaLabel={'Search enterprise teams'}
          />
        </div>
        {searchQuery && (
          <ListView
            title={'Enterprise teams'}
            className="border border-muted rounded-2 mb-3"
            data-testid="licensing-copilot-enterprise-team-grant-access-list"
          >
            {loading ? (
              <ListItem title={<span />}>
                <div className={`text-center p-3 ${styles.stretchedText}`}>Loading enterprise teams...</div>
              </ListItem>
            ) : isEmpty || businessTeams.length === 0 ? (
              <ListItem title={<span />}>
                <div className={`text-center p-3 ${styles.stretchedText}`}>
                  No enterprise teams found matching your search.
                </div>
              </ListItem>
            ) : (
              (businessTeams as BusinessTeam[]).map(team => (
                <ListItem
                  key={team.id}
                  data-testid={`enterprise-team-li-${team.name}`}
                  className={styles.clickableListItem}
                  title={
                    <Button variant="invisible" className={styles.teamDetails} onClick={() => handleTeamSelect(team)}>
                      <div className="d-flex align-items-center">
                        <div className="ml-2">
                          <span className="text-bold">{team.name}</span>
                          <span className="text-small color-fg-muted ml-2">{team.memberCount} members</span>
                        </div>
                      </div>
                    </Button>
                  }
                />
              ))
            )}
          </ListView>
        )}

        {selectedTeams.length > 0 && (
          <div className="mb-1">
            <h3 className="mb-2 text-small text-bold">Selected teams ({selectedTeams.length})</h3>
            <div className={styles.selectedTeamsContainer}>
              {selectedTeams.map(team => (
                <div
                  key={`selected-${team.id}`}
                  data-testid={`selected-enterprise-team-item-${team.name}`}
                  className={styles.selectedTeamItem}
                >
                  <div className="d-flex align-items-center">
                    <span className="text-small text-bold mr-2">{team.name}</span>
                  </div>
                  <Button
                    variant="invisible"
                    size="small"
                    data-testid={`remove-enterprise-team-${team.id}`}
                    className={styles.removeButton}
                    aria-label={`Remove ${team.name}`}
                    onClick={() => handleTeamRemove(team.id)}
                  >
                    <XIcon size={12} />
                  </Button>
                </div>
              ))}
            </div>
          </div>
        )}
      </Dialog>

      {showConfirmationDialog && (
        <CopilotBusinessTeamChangeAccessDialog
          teams={selectedTeams.map(team => team.id)}
          downgrade={false}
          onClose={handleCloseConfirmationDialog}
        />
      )}
    </>
  )
}

try{ CopilotBusinessTeamGrantAccessDialog.displayName ||= 'CopilotBusinessTeamGrantAccessDialog' } catch {}