import {Banner, Dialog} from '@primer/react/experimental'
import {useState} from 'react'
import pluralize from 'pluralize'
import {useNavigate} from '@github-ui/use-navigate'
import styles from '../users/CopilotUserChangeAccessDialog.module.css'
import {clsx} from 'clsx'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {Button} from '@primer/react'
import {verifiedFetch} from '@github-ui/verified-fetch'

interface CopilotBusinessTeamChangeAccessDialogProps {
  teams: number[]
  downgrade: boolean
  onClose: () => void
}

export const CopilotBusinessTeamChangeAccessDialog = ({
  teams,
  downgrade,
  onClose,
}: CopilotBusinessTeamChangeAccessDialogProps) => {
  const navigate = useNavigate()
  const {basePath} = useNavigation()

  const [showPlanChangeError, setShowPlanChangeError] = useState(false)

  const handleLicenseChange = async (teamIDs: number[]) => {
    const formData = new FormData()
    for (const teamID of teamIDs) {
      formData.append('team_ids[]', teamID.toString())
    }

    const endpoint = `${basePath}/enterprise_licensing/enterprise_team_licenses`

    try {
      const response = await verifiedFetch(endpoint, {
        method: downgrade ? 'DELETE' : 'POST',
        body: formData,
      })
      if (response.ok) {
        onClose()
        navigate(`${basePath}/enterprise_licensing/copilot?tab=enterprise_teams`)
      } else {
        setShowPlanChangeError(true)
      }
    } catch {
      setShowPlanChangeError(true)
    }
  }

  return (
    <Dialog
      className={clsx(styles.changeConfirmationDialog)}
      onClose={onClose}
      title={downgrade ? 'Remove Copilot Business licenses' : 'Assign Copilot Business licenses'}
    >
      {showPlanChangeError && (
        <Banner
          title="Copilot license change error"
          hideTitle
          variant="critical"
          onDismiss={() => setShowPlanChangeError(false)}
          className="mb-3"
          data-testid="copilot-license-change-error-banner"
        >
          {'An error occurred while updating the Copilot licenses for this enterprise.'}
        </Banner>
      )}
      <div className={styles.changeConfirmationText} data-testid="copilot-enterprise-team-license-change-dialog">
        <span>
          Do you want to <span>{downgrade ? 'remove' : 'add'}</span> Copilot Business licenses for users of{' '}
          {pluralize('this', teams.length)} <span>{teams.length}</span> {pluralize('team', teams.length)}?
        </span>
        {downgrade === true ? (
          <>
            <p className={'color-fg-muted pb-2 pt-4'}>Users will lose access immediately.</p>
          </>
        ) : (
          <>
            <p className={'color-fg-muted pb-2 pt-4'}>Users will gain access immediately.</p>
          </>
        )}
      </div>
      <div className={styles.dialogActions}>
        <Button variant="default" onClick={onClose}>
          Cancel
        </Button>
        <Button variant={downgrade ? 'danger' : 'primary'} onClick={() => handleLicenseChange(teams)}>
          {downgrade === true ? <>Remove licenses</> : <>Add licenses</>}
        </Button>
      </div>
    </Dialog>
  )
}

try{ CopilotBusinessTeamChangeAccessDialog.displayName ||= 'CopilotBusinessTeamChangeAccessDialog' } catch {}